/**
 * Cookie Consent Banner Handler
 */

\(function\(\) {
    'use strict';

    const CookieConsent = {
        // Configuration
        cookieName: document.querySelector\('[data-site-cookie-name]'\)?.getAttribute\('data-site-cookie-name'\) || 'cookie_for_consent',
        cookieLifetime: parseInt\(document.querySelector\('[data-site-cookie-lifetime]'\)?.getAttribute\('data-site-cookie-lifetime'\) || 31536000\),
        cookieDomain: document.querySelector\('[data-site-cookie-domain]'\)?.getAttribute\('data-site-cookie-domain'\) || window.location.hostname,
        isSecure: document.querySelector\('[data-site-session-secure]'\)?.getAttribute\('data-site-session-secure'\) || '',

        /**
         * Initialize the cookie consent banner
         */
        init: function\(\) {
            // Check if user has already consented
            if \(this.hasConsented\(\)\) {
                this.hideBanner\(\);
                return;
            }

            // Show banner and attach event listeners
            this.showBanner\(\);
            this.attachEventListeners\(\);
        },

        /**
         * Check if user has already consented
         */
        hasConsented: function\(\) {
            return this.getCookie\(this.cookieName\) !== null;
        },

        /**
         * Get cookie value
         */
        getCookie: function\(name\) {
            const nameEQ = name + '=';
            const cookies = document.cookie.split\(';'\);

            for \(let i = 0; i < cookies.length; i++\) {
                const cookie = cookies[i].trim\(\);
                if \(cookie.indexOf\(nameEQ\) === 0\) {
                    return decodeURIComponent\(cookie.substring\(nameEQ.length\)\);
                }
            }

            return null;
        },

        /**
         * Set cookie
         */
        setCookie: function\(name, value, days\) {
            const date = new Date\(\);
            date.setTime\(date.getTime\(\) + \(days * 24 * 60 * 60 * 1000\)\);

            const expires = 'expires=' + date.toUTCString\(\);
            const secure = this.isSecure ? ';secure' : '';
            const sameSite = ';SameSite=Lax';

            document.cookie = name + '=' + encodeURIComponent\(value\) + ';' + expires + ';path=/;domain=' + this.cookieDomain + secure + sameSite;
        },

        /**
         * Show cookie banner
         */
        showBanner: function\(\) {
            const banner = document.querySelector\('.js-cookie-consent'\);
            if \(banner\) {
                banner.style.display = 'flex';
                setTimeout\(\(\) => {
                    banner.classList.add\('visible'\);
                }, 10\);
            }
        },

        /**
         * Hide cookie banner
         */
        hideBanner: function\(\) {
            const banner = document.querySelector\('.js-cookie-consent'\);
            if \(banner\) {
                banner.style.display = 'none';
            }
        },

        /**
         * Handle accept button click
         */
        handleAccept: function\(\) {
            const expiryDays = Math.ceil\(this.cookieLifetime / \(24 * 60 * 60\)\);
            this.setCookie\(this.cookieName, 'accepted', expiryDays\);
            this.hideBanner\(\);

            if \(window.onCookieConsent && typeof window.onCookieConsent === 'function'\) {
                window.onCookieConsent\('accepted'\);
            }
        },

        /**
         * Handle reject button click
         */
        handleReject: function\(\) {
            const expiryDays = Math.ceil\(this.cookieLifetime / \(24 * 60 * 60\)\);
            this.setCookie\(this.cookieName, 'rejected', expiryDays\);
            this.hideBanner\(\);

            if \(window.onCookieConsent && typeof window.onCookieConsent === 'function'\) {
                window.onCookieConsent\('rejected'\);
            }
        },

        /**
         * Attach event listeners to buttons
         */
        attachEventListeners: function\(\) {
            const acceptBtn = document.querySelector\('.js-cookie-consent-agree'\);
            const rejectBtn = document.querySelector\('.js-cookie-consent-reject'\);

            if \(acceptBtn\) {
                acceptBtn.addEventListener\('click', \(\) => this.handleAccept\(\)\);
            }

            if \(rejectBtn\) {
                rejectBtn.addEventListener\('click', \(\) => this.handleReject\(\)\);
            }
        }
    };

    // Initialize on document ready
    if \(document.readyState === 'loading'\) {
        document.addEventListener\('DOMContentLoaded', \(\) => CookieConsent.init\(\)\);
    } else {
        CookieConsent.init\(\);
    }

    // Expose to global scope for external use
    window.CookieConsent = CookieConsent;
}\)\(\);
EOF)
